# So there are two patterns:
# 1) "X forks" (with comma-separated numbers possibly)
# 2) "forks count of X"
# I need a regex that captures both.
# Pattern: (?:([0-9,]+) forks)|(?:forks count of ([0-9,]+))
# Let's use a unified approach in Python

import re
def extract_forks(s):
    if s is None: return None
    # Try "X forks"
    m = re.search(r'([0-9][0-9,]*)\s+forks?\b', s)
    if m:
        return int(m.group(1).replace(',', ''))
    # Try "forks count of X"
    m = re.search(r'forks?\s+count\s+of\s+([0-9][0-9,]*)', s, re.IGNORECASE)
    if m:
        return int(m.group(1).replace(',', ''))
    return None

def extract_project_name(s):
    if s is None: return None
    m = re.search(r'([A-Za-z0-9_.\-]+/[A-Za-z0-9_.\-]+)', s)
    if m:
        return m.group(1)
    return None

# Test
for s in sample_all['Project_Information'].head(20):
    print(extract_project_name(s), "|", extract_forks(s))
